// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// The project's own hooks: the Piezas checks without the plugin
// ===========================================================================
//
// `piezas init` writes the same hooks the plugin brings, at the project level,
// so a project is checked in Claude Code and Codex whether or not the plugin
// is installed:
//   - .piezas/hooks/hook.mjs — a small file that loads the checks from the
//     project's installed CLI (node_modules/piezas inside this project, and
//     nowhere else). When that is missing or cannot start (a fresh clone
//     before `npm install`), a small rule built into the file still keeps the
//     guardrails' own files in place, and the owner is told plainly that the
//     guardrails are not fully running.
//   - .claude/settings.json (`hooks`) — Claude Code runs it after the owner
//     trusts the folder.
//   - .codex/hooks.json — Codex runs it once hooks are on and the owner has
//     approved them in /hooks.
// Every entry passes the event's name to the file (`hook.mjs pre-tool-use`),
// so a tool call is refused even when the event itself cannot be read.
// Existing settings are kept: the Piezas entries are added once (found again
// by their exact command), and a file that is not valid JSON, or a link to a
// file outside the project, is left as it is.
import { spawnSync } from 'child_process';
import { existsSync, lstatSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from 'fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'path';
import { CLI_VERSION, PROJECT_HOOK_MARKER } from './constants.js';
import { PROTECTED_FS_CODES, detail, log } from './core.js';

export const HOOK_SHIM_PATH = PROJECT_HOOK_MARKER; // .piezas/hooks/hook.mjs
export const HOOK_EVENTS = ['SessionStart', 'UserPromptSubmit', 'PreToolUse', 'Stop'];
export const HOOK_EVENT_ARGS = {
  SessionStart: 'session-start',
  UserPromptSubmit: 'user-prompt-submit',
  PreToolUse: 'pre-tool-use',
  Stop: 'stop',
};
export const PRE_TOOL_MATCHER = 'Write|Edit|MultiEdit|NotebookEdit|Bash|apply_patch|exec_command|shell';
export const SESSION_START_MATCHER = 'startup|resume|clear|compact|fork';
// The oldest piezas with the hook entry the shim loads.
export const MIN_HOOK_CLI_VERSION = '0.7.0';

// The command each settings entry runs: a short launcher that finds the
// project's hook file and runs it with the event's name. Claude Code gives
// hooks the project folder ($CLAUDE_PROJECT_DIR): only that folder is used.
// Codex runs hooks in the session's folder (its docs: "Commands run with the
// session cwd as their working directory") and has no project-folder
// variable: the launcher walks up from there to the nearest Piezas project
// folder (the hook file, piezas.manifest.json or .piezas), never above the
// home folder. When the hook file is missing it is no dead end: a tool call
// is refused only when it would change the guardrails' own files (so
// `npx piezas init` and installs go through), and the owner is told the cause
// and the fix at session start and on their message. No project folder at
// all: a tool call is refused. (No double quotes, $, backticks or
// backslashes in it: it runs inside a shell's double quotes.)
export const HOOK_LAUNCHER_SOURCE = String.raw`const p=require('path'),f=require('fs'),u=require('url'),o=require('os');const e=process.argv[1],H=o.homedir();const shim=(d)=>p.join(d,'.piezas','hooks','hook.mjs');const proj=(d)=>f.existsSync(shim(d))||f.existsSync(p.join(d,'piezas.manifest.json'))||f.existsSync(p.join(d,'.piezas'));const miss=(d)=>{let j=null;try{j=JSON.parse(f.readFileSync(0,'utf8'))}catch(x){}const ev=(j&&j.hook_event_name)||({'pre-tool-use':'PreToolUse','session-start':'SessionStart','user-prompt-submit':'UserPromptSubmit','stop':'Stop'})[e];if(ev==='PreToolUse'){if(d===''){console.error('Piezas check could not run; refusing this step. (For the AI: no Piezas project folder was found.)');process.exit(2)}const w=JSON.stringify((j&&j.tool_input)||{}).toLowerCase();if(/[.]piezas[/]hooks|[.]claude[/]settings|[.]codex[/](hooks[.]json|config[.]toml)|node_modules[/]piezas/.test(w)&&/npx piezas init/.test(w)===false){console.error('This would change the files that run the Piezas guardrails, which are not running right now, so it was stopped. (For the AI: the Piezas hook file .piezas/hooks/hook.mjs is missing; run npx piezas init in the project folder first.)');process.exit(2)}process.exit(0)}if(d!==''&&(ev==='SessionStart'||ev==='UserPromptSubmit')){process.stdout.write(JSON.stringify({systemMessage:'Piezas guardrails are not running in this project: their hook file is missing. Ask your AI tool to set them up again (npx piezas init); they start with your next message.',hookSpecificOutput:{hookEventName:ev,additionalContext:'[Piezas] The Piezas hook file (.piezas/hooks/hook.mjs) is missing in this project, so the guardrails are not running. Run npx piezas init in the project folder, then tell the owner in one plain sentence.'}}))}process.exit(0)};let d=process.env.CLAUDE_PROJECT_DIR||'';if(d===''){d=process.cwd();for(;;){if(proj(d))break;const n=p.dirname(d);if(n===d||d===H){d='';break}d=n}}if(d!==''&&f.existsSync(shim(d)))import(u.pathToFileURL(shim(d)).href).catch(()=>miss(d));else miss(d);`;
export const HOOK_LAUNCHER = `node -e "${HOOK_LAUNCHER_SOURCE}"`;
export function claudeHookCommand(event) {
  return `${HOOK_LAUNCHER} ${HOOK_EVENT_ARGS[event]}`;
}
export function codexHookCommand(event) {
  return `${HOOK_LAUNCHER} ${HOOK_EVENT_ARGS[event]}`;
}

export function hookCommand(host, event) {
  return host === 'codex' ? codexHookCommand(event) : claudeHookCommand(event);
}

// Commands an earlier 0.7.0 build wrote (no event name): replaced on init.
export const LEGACY_HOOK_COMMANDS = new Set([
  `node "$CLAUDE_PROJECT_DIR/${HOOK_SHIM_PATH}"`, `node ${HOOK_SHIM_PATH}`,
  ...Object.values(HOOK_EVENT_ARGS).map((a) => `node "$CLAUDE_PROJECT_DIR/${HOOK_SHIM_PATH}" ${a}`),
]);

const MATCHERS = { SessionStart: SESSION_START_MATCHER, PreToolUse: PRE_TOOL_MATCHER };
const TIMEOUTS = { SessionStart: 20, UserPromptSubmit: 20, PreToolUse: 20, Stop: 60 };

// expectedHookEntries — per event, the Piezas entry exactly: { matcher, command }.
export function expectedHookEntries(host) {
  return Object.fromEntries(HOOK_EVENTS.map((event) => [event, { matcher: MATCHERS[event], command: hookCommand(host, event) }]));
}

// The same events, matchers and timeouts as the plugin's hooks/hooks.json.
export function projectHookGroups(host) {
  return Object.fromEntries(HOOK_EVENTS.map((event) => [event, {
    ...(MATCHERS[event] ? { matcher: MATCHERS[event] } : {}),
    hooks: [{ type: 'command', command: hookCommand(host, event), timeout: TIMEOUTS[event] }],
  }]));
}

// The owner-facing words, shared by init's summary and the agent files. The
// reader may not be a developer: one thing to do, said plainly, and the tool
// named only in the prompt it will show. Each tool has a step for its desktop
