// The names for where a tool runs, used when a step is shown with its label.
export const SURFACE_LABELS = {
  'claude-code': { cli: 'Claude Code in a terminal', app: 'Claude app' },
  codex: { cli: 'Codex in a terminal', app: 'Codex app' },
};

// surfaceSteps — the step for where the tool runs, unlabelled, when that is
// known (app true or false); both steps, each with its label, when it is not.
// A labelled step drops its own "In Codex, " (the label already says it), so
// it never reads "Claude app: In the Claude app, ..."; an unlabelled one is
// shown whole.
const TOOL_LEAD = /^In (?:the )?(?:Claude app|Claude Code|Codex app|Codex), /;
function labelled(host, where, text) {
  const rest = text.replace(TOOL_LEAD, '');
  return `${SURFACE_LABELS[host][where]}: ${rest === text ? text : rest.charAt(0).toUpperCase() + rest.slice(1)}`;
}
export function surfaceSteps(texts, host, app) {
  if (app === true) return [texts.app];
  if (app === false) return [texts.cli];
  return [labelled(host, 'cli', texts.cli), labelled(host, 'app', texts.app)];
}

